STATUS = "Plain general-knowledge lesson for Class 8-12 students - edit freely"


def lesson_rows():
    rows = []
    for lid, topic, careers, tags, en, hi, mr in LESSONS:
        rows.append([lid, topic, careers, tags, *en, *hi, *mr, STATUS])
    return rows


